QJsonObject RouterTools::portsPlan(QJsonObject t,QString selected,QString internet,QString management){if(internet.isEmpty())internet=wan(t);check(!selected.isEmpty()&&!internet.isEmpty(),"WAN_CLIENT_REQUIRED");bool bridge=!find(t,"interface/bridge","name",selected).isEmpty();auto target=bridge?selected:"fg-clients";QSet<QString> occupied,protectedPorts;for(auto m:{"interface/bridge/port","interface/vlan","ip/dhcp-client","interface/pppoe-client"})for(auto r:rows(t,m)){occupied.insert(str(r,"interface"));protectedPorts.insert(str(r,"interface"));}protectedPorts.insert(internet);for(auto r:rows(t,"interface/list/member"))if(str(r,"list").compare("WAN",Qt::CaseInsensitive)==0)protectedPorts.insert(str(r,"interface"));for(auto m:{"ip/address","ip/dhcp-server","ip/hotspot"})for(auto r:rows(t,m))if(r["interface"]!=selected)occupied.insert(str(r,"interface"));for(auto r:rows(t,"ip/address"))if(r["interface"]==selected)check(!management.contains(str(r,"address").section('/',0,0)),"USE_WAN_SIDE_MANAGEMENT");if(!bridge){check(find(t,"interface","name",target).isEmpty()&&!protectedPorts.contains(selected)&&!occupied.contains(selected),"CLIENT_PORT_OCCUPIED");auto port=find(t,"interface","name",selected);check(port["type"]=="ether"||QRegularExpression("^ether[0-9]+$").match(selected).hasMatch(),"PHYSICAL_CLIENT_PORT_REQUIRED");for(auto m:{"ip/firewall/filter","ip/firewall/nat"})for(auto r:rows(t,m))check(r["in-interface"]!=selected&&r["out-interface"]!=selected,"INTERFACE_FIREWALL_REVIEW");}QJsonArray changes;if(!bridge){changes.append(change("interface/bridge","add",{{"name",target},{"comment","FG MTM customer network"}},{},"إنشاء جسر العملاء • Create client bridge"));for(auto m:{"ip/address","ip/dhcp-server","ip/hotspot","interface/list/member"})for(auto r:rows(t,m))if(r["interface"]==selected){check(!str(r,".id").isEmpty()&&!yes(r,"dynamic"),"DYNAMIC_CLIENT_SETTING");changes.append(change(m,"set",{{".id",r[".id"]},{"interface",target}},{{".id",r[".id"]},{"interface",selected}},"نقل الإعداد للجسر • Move client configuration"));}}
 QStringList ports;if(!bridge)ports.append(selected);for(auto r:rows(t,"interface")){auto n=str(r,"name");if(n!=selected&&!occupied.contains(n)&&!protectedPorts.contains(n)&&enabled(r)&&!yes(r,"running")&&(r["type"]=="ether"||QRegularExpression("^ether[0-9]+$").match(n).hasMatch()))ports.append(n);}for(auto port:ports)changes.append(change("interface/bridge/port","add",{{"bridge",target},{"interface",port}},{},"ضم المنفذ • Group port "+port));return {{"kind","PORTS"},{"changes",changes},{"bridge",target}};}
QJsonObject RouterTools::dnsPlan(QJsonObject t,QSet<QString> selected,QString mode){check(!selected.isEmpty()&&selected.size()<=32&&QStringList{"FAMILY","ADS_TRACKERS"}.contains(mode),"SELECT_CLIENT_NETWORK");auto servers=mode=="FAMILY"?"94.140.14.15,94.140.15.16":"94.140.14.14,94.140.15.15";QJsonArray changes;auto add=[&](QString menu,QJsonObject r,QJsonObject after){QJsonObject changed,before;for(auto it=after.begin();it!=after.end();++it)if(normalized(str(r,it.key()))!=normalized(it.value().toString())){changed[it.key()]=it.value();before[it.key()]=str(r,it.key());}if(!changed.isEmpty()){if(menu!="ip/dns"){changed[".id"]=r[".id"];before[".id"]=r[".id"];}auto step=change(menu,"set",changed,before,str(r,"address",menu));step["targetAddress"]=str(r,"address");step["targetInterface"]=str(r,"interface");changes.append(step);}};check(t["ip/dns"].toArray().size()==1,"DNS_READ_REQUIRED");auto dns=t["ip/dns"].toArray().first().toObject();QJsonObject settings{{"servers",servers}};if(dns.contains("use-doh-server"))settings["use-doh-server"]="";add("ip/dns",dns,settings);int count=0;for(auto r:rows(t,"ip/dhcp-server/network"))if(selected.contains(str(r,".id"))){check(privateSubnet(str(r,"address"))&&str(r,"dhcp-option").isEmpty()&&str(r,"dhcp-option-set").isEmpty(),"DHCP_OPTIONS_OR_PUBLIC_NETWORK_REVIEW");QJsonObject attrs{{"dns-server",servers}};if(r.contains("dns-none"))attrs["dns-none"]="no";add("ip/dhcp-server/network",r,attrs);count++;}check(count==selected.size(),"SELECT_CLIENT_NETWORK");for(auto menu:{"ip/dhcp-client","interface/pppoe-client"})for(auto r:rows(t,menu))if(enabled(r)&&yes(r,"use-peer-dns")){check(!str(r,".id").isEmpty(),"TARGET_ID_REQUIRED");add(menu,r,{{"use-peer-dns","no"}});}check(changes.size()<=128,"DNS_CHANGE_LIMIT");return {{"kind","DNS"},{"mode",mode},{"changes",changes},{"servers",servers}};}
QJsonObject RouterTools::renderPortal(QJsonObject design){auto color=str(design,"color","#159DFF");check(QRegularExpression("^#[a-fA-F0-9]{6}$").match(color).hasMatch(),"INVALID_COLOR");auto logo=str(design,"logoDataUri");if(!QRegularExpression("^data:image/(png|jpeg|webp);base64,[A-Za-z0-9+/=]+$").match(logo).hasMatch())logo.clear();auto website=str(design,"website");if(!website.startsWith("https://"))website.clear();QJsonObject assets;QDir dir(":/resources/hotspot");for(auto name:dir.entryList(QDir::Files)){QFile f(dir.filePath(name));check(f.open(QIODevice::ReadOnly),"PORTAL_ASSET_MISSING");auto content=QString::fromUtf8(f.readAll());for(auto pair:QList<QPair<QString,QString>>{{"NETWORK",str(design,"networkName","FG Machines WiFi").toHtmlEscaped()},{"PHONE",str(design,"supportPhone").toHtmlEscaped()},{"WELCOME",str(design,"welcome").toHtmlEscaped()},{"COLOR",color},{"TERMS",str(design,"terms").toHtmlEscaped()},{"WEBSITE",website.toHtmlEscaped()},{"LOGO",logo}})content.replace("@@"+pair.first+"@@",pair.second);check(content.toUtf8().size()<60000,"PORTAL_FILE_LIMIT");assets[name]=content;}check(assets.contains("login.html")&&assets.contains("status.html")&&assets.contains("md5.js"),"PORTAL_ASSET_MISSING");return assets;}
QString RouterTools::signature()const{QJsonObject stable;QSet<QString> keys{".id","name","interface","address","ranges","profile","address-pool","disabled","servers","allow-remote-requests","chain","action","src-address","out-interface","dst-address","gateway","login-by","dns-name","html-directory","html-directory-override","group","network","lease-time","dns-server","netmask","port","certificate","hotspot-address","in-interface","out-interface-list","in-interface-list","protocol","dst-port","src-port","bridge","pvid","vlan-id","vlan-filtering","connection-state","to-addresses","to-ports","list","use-doh-server","use-peer-dns","dns-none","dhcp-option","dhcp-option-set"};for(auto menu:tables.keys()){if(QStringList{"system/resource","system/clock","system/scheduler","ip/hotspot/user","ip/hotspot/active"}.contains(menu))continue;QStringList values;for(auto r:rows(tables,menu)){if(yes(r,"dynamic"))continue;if(menu=="file"&&!QStringList{"login.html","status.html","md5.js"}.contains(str(r,"name").section('/',-1)))continue;QJsonObject kept;for(auto k:r.keys())if(keys.contains(k))kept[k]=r[k];values.append(QString::fromUtf8(QJsonDocument(kept).toJson(QJsonDocument::Compact)));}values.sort();QJsonArray list;for(auto v:values)list.append(v);stable[menu]=list;}return QString::fromLatin1(QCryptographicHash::hash(QJsonDocument(stable).toJson(QJsonDocument::Compact),QCryptographicHash::Sha256).toHex());}
QString RouterTools::fingerprint()const{QStringList macs;for(auto r:rows(tables,"interface"))if(r["type"]=="ether"&&!str(r,"mac-address").isEmpty())macs.append(str(r,"mac-address").toUpper());macs.removeDuplicates();macs.sort();check(!macs.isEmpty(),"ROUTER_IDENTITY_REQUIRED");return QString::fromLatin1(QCryptographicHash::hash(macs.join(',').toUtf8(),QCryptographicHash::Sha256).toHex());}
QString RouterTools::journalPath()const{auto dir=QStandardPaths::writableLocation(QStandardPaths::AppLocalDataLocation)+"/router-journals";QDir().mkpath(dir);return dir+"/"+QString::fromLatin1(QCryptographicHash::hash(client->identityKey().toUtf8(),QCryptographicHash::Sha256).toHex())+".fgj";}
void RouterTools::persist(){auto clear=QJsonDocument(journal).toJson(QJsonDocument::Compact);auto cipher=Vault::protect(clear);clear.fill('\0');QSaveFile f(journalPath());check(f.open(QIODevice::WriteOnly)&&f.write(cipher)==cipher.size()&&f.commit(),"RECOVERY_JOURNAL_WRITE_FAILED");}
void RouterTools::loadJournal(){journal={};QFile f(journalPath());if(!f.exists())return;check(f.open(QIODevice::ReadOnly)&&f.size()<=20*1024*1024,"RECOVERY_JOURNAL_UNREADABLE");auto clear=Vault::unprotect(f.readAll());QJsonParseError error;journal=QJsonDocument::fromJson(clear,&error).object();clear.fill('\0');check(error.error==QJsonParseError::NoError,"RECOVERY_JOURNAL_INVALID");}
