 if(selected.isEmpty()){for(auto r:rows(t,"ip/address"))if(r["interface"]!=internet&&!yes(r,"dynamic")){selected=str(r,"interface");break;}}
 if(selected.isEmpty()){for(auto r:rows(t,"interface")){auto name=str(r,"name");if(name!=internet&&enabled(r)&&(r["type"]=="ether"||name.startsWith("ether"))&&find(t,"interface/bridge/port","interface",name).isEmpty()&&find(t,"ip/dhcp-client","interface",name).isEmpty()&&find(t,"interface/pppoe-client","interface",name).isEmpty()){selected=name;break;}}}
