 auto iface=find(t,"interface","name",internet);add("wan","شبكة الإنترنت","WAN",{"interface","ip/route"},!iface.isEmpty()&&enabled(iface)&&yes(iface,"running"),internet+(internet.isEmpty()?"":" • "+str(detected,"source")));
