 auto dns=rows(t,"ip/dns");auto resolver=dns.isEmpty()?QJsonObject{}:dns.first();add("dns","أسماء المواقع","DNS",{"ip/dns"},!str(resolver,"servers").isEmpty()||!str(resolver,"dynamic-servers").isEmpty(),str(resolver,"servers")+" "+str(resolver,"dynamic-servers"));
 bool bridge=false;for(auto r:rows(t,"interface/bridge"))if(enabled(r))bridge=true;add("bridge","ربط منافذ العملاء","Client bridge",{"interface/bridge"},bridge);
 auto client=find(t,"interface","name",selected);add("client","شبكة العملاء","Client network",{"interface"},!client.isEmpty()&&enabled(client),selected);
 add("ip","عنوان شبكة العملاء","Client gateway address",{"ip/address","interface"},!address.isEmpty(),str(address,"address"));
 add("dhcp","توزيع عناوين العملاء","Client address distribution",{"ip/dhcp-server","interface"},!dhcp.isEmpty(),str(dhcp,"name"));
 auto cidr=str(address,"address");auto subnet=validCidr(cidr)?network(cidr):QString{};auto networkRow=find(t,"ip/dhcp-server/network","address",subnet);
 add("dhcp-network","بوابة العملاء وأسماء المواقع","Client gateway/DNS assignment",{"ip/dhcp-server/network","ip/address"},!networkRow.isEmpty()&&!str(networkRow,"gateway").isEmpty()&&!str(networkRow,"dns-server").isEmpty(),subnet);
 auto pool=find(t,"ip/pool","name",str(dhcp,"address-pool"));add("pool","مدى عناوين العملاء","Client address pool",{"ip/pool","ip/dhcp-server"},!pool.isEmpty()&&!str(pool,"ranges").isEmpty(),str(pool,"ranges"));
 add("hotspot","دخول العملاء بالكروت","HotSpot",{"ip/hotspot","interface"},!hotspot.isEmpty(),str(hotspot,"name"));
 bool login=false;for(auto method:str(profile,"login-by").split(','))if(method=="http-chap"||method=="https")login=true;
