 bool api=false;for(auto r:rows(t,"ip/service"))if(enabled(r)&&QStringList{"api","api-ssl","www","www-ssl"}.contains(str(r,"name")))api=true;add("api","اتصال إدارة الراوتر","RouterOS API",{"ip/service"},api);
