 auto resources=rows(t,"system/resource");auto resource=resources.isEmpty()?QJsonObject{}:resources.first();auto cpu=usageNumber(resource["cpu-load"]),total=usageNumber(resource["total-memory"]),free=usageNumber(resource["free-memory"]);
