 int drops=0;for(auto r:rows(t,"ip/firewall/filter"))if(enabled(r)&&r["chain"]=="forward"&&QStringList{"drop","reject"}.contains(str(r,"action")))drops++;
 add("firewall","قواعد حماية الشبكة","Firewall review",{"ip/firewall/filter"},drops==0,QString::number(drops)+" • "+QString::fromUtf8("وجود قواعد حجب يحتاج مراجعة ترتيبها • Review the order of drop rules"));
