     recovery.append(step);journal["attempted"]=recovery;persist();auto reply=co_await call(menu,action,attrs,false);if(!reply.ok())throw std::runtime_error((reply.error+(reply.uncertain?"; CHANGE_OUTCOME_UNKNOWN":"")).toStdString());
