QVariantMap RouterTools::portalDesign()const{QSettings settings;return settings.value("portal/design").toMap();}
void RouterTools::savePortalDesign(QJsonObject design){try{renderPortal(design);QSettings settings;settings.setValue("portal/design",design.toVariantMap());settings.sync();check(settings.status()==QSettings::NoError,"DESIGN_SAVE_FAILED");message="حُفظ تصميم الصفحة • Portal design saved";}catch(const std::exception&e){message=e.what();}emit changed();}
QString RouterTools::portalLogo(QUrl path){try{QFile file(path.toLocalFile());check(file.exists()&&file.size()<=8*1024*1024,"LOGO_FILE_LIMIT");QImageReader reader(path.toLocalFile());auto size=reader.size();check(size.isValid()&&size.width()<=4096&&size.height()<=4096,"LOGO_IMAGE_LIMIT");reader.setAutoTransform(true);auto image=reader.read();check(!image.isNull(),"INVALID_LOGO_IMAGE");image=image.scaled(256,256,Qt::KeepAspectRatio,Qt::SmoothTransformation);QByteArray bytes;QBuffer buffer(&bytes);buffer.open(QIODevice::WriteOnly);check(image.save(&buffer,"PNG")&&bytes.size()<=35000,"LOGO_TOO_LARGE");return "data:image/png;base64,"+QString::fromLatin1(bytes.toBase64());}catch(const std::exception&e){message=e.what();emit changed();return {};}}

QVariantList RouterTools::backups()const{QVariantList list;if(!client->authorized())return list;for(auto row:tables["file"].toArray()){auto item=row.toObject();auto name=str(item,"name");if(name.endsWith(".backup")||name.endsWith(".rsc"))list.append(QVariantMap{{"name",name},{"size",str(item,"size")},{"date",str(item,"creation-time")}});}return list;}
void RouterTools::loadBackups(){launch("backup_list");}
void RouterTools::repairDns(){launch("repair_dns");}
QString RouterTools::backupPassword(QString file){try{check(client->authorized(),"ACCESS_DENIED");loadJournal();auto password=str(journal["backups"].toObject(),file);check(!password.isEmpty(),"BACKUP_PASSWORD_NOT_SAVED");return password;}catch(const std::exception&e){message=e.what();emit changed();return {};}}

QJsonObject RouterTools::pingEvidence(QJsonArray data){int sent=data.size(),received=0,samples=0;double sum=0;auto ms=[](QString text)->std::optional<double>{auto matches=QRegularExpression("([0-9.]+)(ms|us)").globalMatch(text);double value=0;bool found=false;while(matches.hasNext()){auto match=matches.next();bool valid;auto n=match.captured(1).toDouble(&valid);if(!valid)return {};value+=n/(match.captured(2)=="us"?1000:1);found=true;}if(found)return value;bool valid;value=text.toDouble(&valid);return valid?std::optional<double>(value):std::nullopt;};std::optional<double> latency;for(auto value:data){auto row=value.toObject();if(row.contains("sent")){sent=str(row,"sent").toInt();received=str(row,"received").toInt();latency=ms(str(row,"avg-rtt"));break;}if(!str(row,"time").isEmpty()&&str(row,"status").isEmpty()){received++;if(auto duration=ms(str(row,"time"))){sum+=*duration;samples++;}}}if(!latency&&samples)latency=sum/samples;return {{"sent",sent},{"received",received},{"loss_percent",sent>0?QJsonValue(100.0*(sent-received)/sent):QJsonValue::Null},{"latency_ms",latency?QJsonValue(*latency):QJsonValue::Null}};}
